import { describe, test, expect, beforeEach, mock, spyOn } from 'bun:test';
import { PathNormalizationService } from './PathNormalizationService';
import { TestPathNormalizationAdapter, NoRepositoryAdapter } from '../adapters/TestPathNormalizationAdapter';
import type { PathNormalizationAdapter } from '../adapters/PathNormalizationAdapter';
import type { UniversalAgentSessionEvent } from '../types/UniversalAgentSessionEvent';

describe('PathNormalizationService', () => {
  let service: PathNormalizationService;
  let adapter: PathNormalizationAdapter;

  beforeEach(() => {
    adapter = new TestPathNormalizationAdapter();
    service = new PathNormalizationService(adapter);
  });

  describe('normalizePaths()', () => {
    test('should normalize event with file in repository', async () => {
      const event: UniversalAgentSessionEvent = {
        eventType: 'pre-tool-use',
        sessionId: 'test-session',
        workingDirectory: '/Users/test/project',
        transcriptPath: '/Users/test/.claude/transcript.jsonl',
        timestamp: Date.now(),
        provider: 'claude',
        toolName: 'Read',
        toolInput: { file_path: '/Users/test/project/src/index.ts' },
        rawFilePaths: ['/Users/test/project/src/index.ts'],
        operation: 'read',
        raw: {}
      };

      const result = await service.normalizePaths(event);

      expect(result.files).toBeDefined();
      expect(result.files).toHaveLength(1);
      expect(result.files![0].repository).toBeDefined();
      expect(result.files![0].repository?.relativePath).toBe('src/index.ts');
      expect(result.files![0].repository?.gitRoot).toBe('/Users/test/project');
      expect(result.files![0].displayPath).toBe('src/index.ts');
      expect(result.normalizedWorkingDirectory).toBe('/Users/test/project');
      expect(result.rawFilePaths).toBeUndefined(); // Should be removed
    });

    test('should handle files outside repositories', async () => {
      const event: UniversalAgentSessionEvent = {
        eventType: 'pre-tool-use',
        sessionId: 'test-session',
        workingDirectory: '/tmp',
        transcriptPath: '/tmp/transcript.jsonl',
        timestamp: Date.now(),
        provider: 'claude',
        toolName: 'Read',
        toolInput: { file_path: '/tmp/test.txt' },
        rawFilePaths: ['/tmp/test.txt'],
        operation: 'read',
        raw: {}
      };

      const result = await service.normalizePaths(event);

      expect(result.files).toBeDefined();
      expect(result.files).toHaveLength(1);
      expect(result.files![0].repository).toBeUndefined();
      expect(result.files![0].absolutePath).toBe('/tmp/test.txt');
      expect(result.files![0].displayPath).toBe('/tmp/test.txt');
      expect(result.normalizedWorkingDirectory).toBe('/tmp');
    });

    test('should handle multiple files in different repositories', async () => {
      const event: UniversalAgentSessionEvent = {
        eventType: 'post-tool-use',
        sessionId: 'test-session',
        workingDirectory: '/Users/test/project1',
        transcriptPath: '/Users/test/.claude/transcript.jsonl',
        timestamp: Date.now(),
        provider: 'claude',
        toolName: 'Grep',
        toolInput: { pattern: 'test' },
        rawFilePaths: [
          '/Users/test/project1/src/index.ts',
          '/Users/test/project2/lib/utils.js',
          '/tmp/scratch.txt'
        ],
        operation: 'search',
        raw: {}
      };

      const result = await service.normalizePaths(event);

      expect(result.files).toBeDefined();
      expect(result.files).toHaveLength(3);

      // First file in project1 (same as working dir - minimal info)
      expect(result.files![0].repository?.relativePath).toBe('src/index.ts');
      expect(result.files![0].repository?.repo).toBeUndefined(); // Omitted since it's in event.repository

      // Second file in project2 (different repo - full info)
      expect(result.files![1].repository?.relativePath).toBe('lib/utils.js');
      expect(result.files![1].repository?.repo).toBe('project2');

      // Third file outside any repository
      expect(result.files![2].repository).toBeUndefined();
      expect(result.files![2].absolutePath).toBe('/tmp/scratch.txt');
    });

    test('should handle relative paths', async () => {
      const event: UniversalAgentSessionEvent = {
        eventType: 'pre-tool-use',
        sessionId: 'test-session',
        workingDirectory: '/Users/test/project',
        transcriptPath: '/Users/test/.claude/transcript.jsonl',
        timestamp: Date.now(),
        provider: 'claude',
        toolName: 'Read',
        toolInput: { file_path: './src/index.ts' },
        rawFilePaths: ['./src/index.ts'],
        operation: 'read',
        raw: {}
      };

      const result = await service.normalizePaths(event);

      expect(result.files).toBeDefined();
      expect(result.files).toHaveLength(1);
      expect(result.files![0].originalPath).toBe('./src/index.ts');
      expect(result.files![0].absolutePath).toBe('/Users/test/project/src/index.ts');
      expect(result.files![0].repository?.relativePath).toBe('src/index.ts');
    });

    test('should handle events without file paths', async () => {
      const event: UniversalAgentSessionEvent = {
        eventType: 'notification',
        sessionId: 'test-session',
        workingDirectory: '/Users/test/project',
        transcriptPath: '/Users/test/.claude/transcript.jsonl',
        timestamp: Date.now(),
        provider: 'claude',
        data: { message: 'Test notification' },
        raw: {}
      };

      const result = await service.normalizePaths(event);

      expect(result.files).toBeUndefined();
      expect(result.normalizedWorkingDirectory).toBe('/Users/test/project');
    });

    test('should preserve all other event properties', async () => {
      const event: UniversalAgentSessionEvent = {
        eventType: 'pre-tool-use',
        sessionId: 'test-session',
        workingDirectory: '/Users/test/project',
        transcriptPath: '/Users/test/.claude/transcript.jsonl',
        timestamp: 1234567890,
        provider: 'claude',
        toolName: 'Edit',
        toolInput: { file_path: '/Users/test/project/index.ts', old_string: 'foo', new_string: 'bar' },
        toolOutput: { success: true },
        rawFilePaths: ['/Users/test/project/index.ts'],
        operation: 'edit',
        data: { custom: 'data' },
        raw: { original: 'event' }
      };

      const result = await service.normalizePaths(event);

      // Check that all properties except rawFilePaths are preserved
      expect(result.eventType).toBe('pre-tool-use');
      expect(result.sessionId).toBe('test-session');
      expect(result.transcriptPath).toBe('/Users/test/.claude/transcript.jsonl');
      expect(result.timestamp).toBe(1234567890);
      expect(result.provider).toBe('claude');
      expect(result.toolName).toBe('Edit');
      expect(result.toolInput).toEqual({ file_path: '/Users/test/project/index.ts', old_string: 'foo', new_string: 'bar' });
      expect(result.toolOutput).toEqual({ success: true });
      expect(result.operation).toBe('edit');
      expect(result.data).toEqual({ custom: 'data' });
      expect(result.raw).toEqual({ original: 'event' });
    });
  });

  describe('normalizePath()', () => {
    test('should handle special characters in file paths', async () => {
      const filePath = "/Users/test/project/file with spaces (and parens).ts";
      const workingDirectory = '/Users/test/project';

      const result = await service.normalizePath(filePath, workingDirectory);

      expect(result.originalPath).toBe(filePath);
      expect(result.absolutePath).toBe(filePath);
      expect(result.repository?.relativePath).toBe('file with spaces (and parens).ts');
    });

    test('should handle deeply nested paths', async () => {
      const filePath = '/Users/test/project/src/components/ui/buttons/PrimaryButton.tsx';
      const workingDirectory = '/Users/test/project';

      const result = await service.normalizePath(filePath, workingDirectory);

      expect(result.repository?.relativePath).toBe('src/components/ui/buttons/PrimaryButton.tsx');
      expect(result.displayPath).toBe('src/components/ui/buttons/PrimaryButton.tsx');
    });
  });

  describe('normalizeWorkingDirectory()', () => {
    test('should return repository root when in a repository', async () => {
      const result = await service.normalizeWorkingDirectory('/Users/test/project/src/nested');
      expect(result).toBe('/Users/test/project');
    });

    test('should return original path when not in a repository', async () => {
      const result = await service.normalizeWorkingDirectory('/tmp/scratch');
      expect(result).toBe('/tmp/scratch');
    });
  });
});

// Test with a minimal adapter that returns null for everything
describe('PathNormalizationService with no repositories', () => {
  test('should handle adapter that finds no repositories', async () => {
    const adapter = new NoRepositoryAdapter();
    const service = new PathNormalizationService(adapter);
    const event: UniversalAgentSessionEvent = {
      eventType: 'pre-tool-use',
      sessionId: 'test',
      workingDirectory: '/work',
      transcriptPath: '/transcript.jsonl',
      timestamp: Date.now(),
      provider: 'claude',
      rawFilePaths: ['/work/file.ts'],
      raw: {}
    };

    const result = await service.normalizePaths(event);
    expect(result.files![0].repository).toBeUndefined();
    expect(result.files![0].absolutePath).toBe('/work/file.ts');
  });
});

// Test optimization: getRawRepositoryInfo should only be called once for files in same repo
describe('PathNormalizationService Optimization', () => {
  test('should call getRawRepositoryInfo only once for files in the same repository', async () => {
    const adapter = new TestPathNormalizationAdapter();
    const getRawRepositoryInfoSpy = spyOn(adapter, 'getRawRepositoryInfo');

    const service = new PathNormalizationService(adapter);

    const event: UniversalAgentSessionEvent = {
      eventType: 'pre-tool-use',
      sessionId: 'test-session',
      workingDirectory: '/Users/test/project',
      timestamp: Date.now(),
      provider: 'claude',
      rawFilePaths: [
        '/Users/test/project/src/index.ts',
        '/Users/test/project/src/utils.ts',
        '/Users/test/project/tests/index.test.ts',
        'README.md', // Relative path in same repo
      ],
      raw: {}
    };

    const result = await service.normalizePaths(event);

    // Should only call getRawRepositoryInfo ONCE (for working directory)
    expect(getRawRepositoryInfoSpy).toHaveBeenCalledTimes(1);
    expect(getRawRepositoryInfoSpy).toHaveBeenCalledWith('/Users/test/project');

    // Event should have repository info at the top level
    expect(result.repository).toBeDefined();
    expect(result.repository?.root).toBe('/Users/test/project');
    expect(result.repository?.owner).toBe('test');
    expect(result.repository?.repo).toBe('project');

    // Files should have minimal repository info (for backward compatibility)
    expect(result.files).toHaveLength(4);
    result.files?.forEach((file) => {
      expect(file.repository).toBeDefined();
      expect(file.repository?.gitRoot).toBe('/Users/test/project');
      expect(file.repository?.relativePath).toBeDefined();
      // These fields should be omitted since they're in event.repository
      expect(file.repository?.owner).toBeUndefined();
      expect(file.repository?.repo).toBeUndefined();
      expect(file.repository?.remoteUrl).toBeUndefined();
    });
  });

  test('should call getRawRepositoryInfo for files in different repositories', async () => {
    const adapter = new TestPathNormalizationAdapter();
    const getRawRepositoryInfoSpy = spyOn(adapter, 'getRawRepositoryInfo');

    const service = new PathNormalizationService(adapter);

    const event: UniversalAgentSessionEvent = {
      eventType: 'pre-tool-use',
      sessionId: 'test-session',
      workingDirectory: '/Users/test/project',
      timestamp: Date.now(),
      provider: 'claude',
      rawFilePaths: [
        '/Users/test/project/src/index.ts', // Same repo as working dir
        '/tmp/test.txt', // Not in any repo
        '/Users/test/other-project/main.ts', // Would be in different repo
      ],
      raw: {}
    };

    const result = await service.normalizePaths(event);

    // Should call getRawRepositoryInfo:
    // 1. Once for working directory
    // 2. Once for /tmp/test.txt (returns null)
    // 3. Once for /Users/test/other-project/main.ts (would return different repo)
    expect(getRawRepositoryInfoSpy.mock.calls.length).toBeGreaterThanOrEqual(3);

    // Event should have repository info for the working directory
    expect(result.repository?.root).toBe('/Users/test/project');

    // First file should have minimal repository info (same as working dir)
    expect(result.files?.[0].repository).toBeDefined();
    expect(result.files?.[0].repository?.gitRoot).toBe('/Users/test/project');
    expect(result.files?.[0].repository?.owner).toBeUndefined();

    // Second file should not have repository info (not in any repo)
    expect(result.files?.[1].repository).toBeUndefined();
    expect(result.files?.[1].displayPath).toBe('/tmp/test.txt');
  });
});